(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,40333,e=>{"use strict";let t=[{id:"the-agentic-loop",domainId:"agentic-architecture",title:"The Agentic Loop",summary:"The core runtime pattern behind every Claude agent: reason, act through tools, observe results, and repeat until a stop condition is met.",objectives:["Describe each phase of the agentic loop and what flows between them","Explain why tool results must be fed back into the conversation as observations","Choose stop conditions that prevent both premature exits and runaway loops","Identify the production risks introduced by unbounded loops"],explanation:{heading:"Concept",body:["An agent is not a single model call. It is a loop in which Claude repeatedly decides the next action, executes it through a tool, observes the structured result, and updates its plan. The model never touches your systems directly. It proposes tool calls; your runtime executes them and returns observations.","The loop closes when a stop condition fires: the model emits a final answer, a budget is exhausted (turns, tokens, time, or cost), or a required human approval gate halts execution. Everything else in agentic design, including orchestration, subagents, and handoffs, is an extension of this one pattern."]},whyItMatters:["Domain 1 carries the heaviest exam weight (27%), and nearly every scenario assumes you can trace what happens on each iteration of the loop.","Most production incidents in agent systems are loop failures: missing observations, absent budgets, or stop conditions that never fire.","Cost and latency scale with iterations, so loop design is where architectural trade-offs become concrete."],diagram:"agentic-loop",simpleExample:{title:"A two-tool support agent",body:"Claude answers billing questions using lookup_invoice and refund_status. Each turn it may call one tool; your code runs it and appends the result as an observation.",code:{label:"agent.ts",language:"typescript",code:`import Anthropic from "@anthropic-ai/sdk";

const client = new Anthropic();

const tools = [
  {
    name: "lookup_invoice",
    description:
      "Look up an invoice by ID. Returns status, amount, and due date. Use for any question about a specific invoice.",
    input_schema: {
      type: "object" as const,
      properties: { invoice_id: { type: "string" } },
      required: ["invoice_id"],
    },
  },
  {
    name: "refund_status",
    description:
      "Get the current status of a refund request. Returns state and last update time.",
    input_schema: {
      type: "object" as const,
      properties: { refund_id: { type: "string" } },
      required: ["refund_id"],
    },
  },
];

async function runAgent(userGoal: string, maxTurns = 8) {
  const messages = [{ role: "user", content: userGoal }];

  for (let turn = 0; turn < maxTurns; turn++) {
    const response = await client.messages.create({
      model: "claude-sonnet-4-5",
      max_tokens: 1024,
      system: "Answer billing questions. Use tools before stating facts.",
      messages,
      tools,
    });

    messages.push({ role: "assistant", content: response.content });

    if (response.stop_reason !== "tool_use") {
      return response;
    }

    const toolUseBlocks = response.content.filter(
      (b) => b.type === "tool_use"
    );
    const results = await Promise.all(
      toolUseBlocks.map(async (call) => ({
        type: "tool_result" as const,
        tool_use_id: call.id,
        content: JSON.stringify(await executeTool(call.name, call.input)),
      }))
    );

    messages.push({ role: "user", content: results });
  }

  throw new Error("Turn budget exhausted before completion");
}

async function executeTool(name: string, input: unknown) {
  if (name === "lookup_invoice") {
    return { status: "overdue", amount_usd: 240, days_late: 6 };
  }
  return { state: "processing", updated_at: "2026-08-20T14:03:00Z" };
}`}},productionExample:{title:"Refund triage service at an e-commerce company",body:"A payments team wraps the same loop in production guardrails: every tool result is validated against a schema before re-entering the prompt, the loop enforces a hard budget of 10 turns and $0.40 of token spend, and any refund above $200 routes to a human approval queue instead of executing. Structured logs record each iteration with inputs, outputs, latency, and cost so regressions are debuggable. The loop itself did not change from the simple example. What changed is that every exit path became explicit."},antiPattern:{name:"Fire-and-forget tool calls",wrong:"Executing tool calls but appending only the assistant's text to history, discarding the structured tool_result blocks.",consequence:"The model loses its observations, re-plans from stale assumptions, repeats calls it already made, or confidently invents results it never saw. Costs climb while quality collapses.",fix:"Always append a user message containing one tool_result block per tool_use block, keyed by tool_use_id, before the next model call."},tradeOffs:[{choice:"Higher turn budget",gain:"Complex multi-step tasks complete without manual restarts",cost:"Runaway loops multiply token spend and latency when the model thrashes"},{choice:"More tools per turn",gain:"Fewer iterations because the model can parallelize independent actions",cost:"Larger tool surface confuses selection and degrades accuracy per call"},{choice:"Strict stop conditions",gain:"Predictable worst-case cost and bounded incident blast radius",cost:"Legitimately long tasks terminate early unless budgets are tuned per task class"}],handsOn:{title:"Trace the loop by hand",steps:["Clone the simple example and add console.log of the full messages array after every append.","Ask: 'Is invoice inv_881 overdue, and has my refund r_21 landed?' and count how many loop iterations run.","Break it on purpose: comment out the tool_result append and watch the model hallucinate or repeat calls.","Set maxTurns to 2 and confirm the budget error fires instead of an infinite loop.","Finish the linked MCP lab to see the same loop driven through real external tools."],linkedLabId:"tool-use-app"},examQuestionId:"q-agentic-loop-stop",takeaway:"An agent is a budgeted loop of decisions and observations. Design the exit paths first, then let the model improvise inside them.",tags:["agentic loop","tool use","stop conditions","state management"]},{id:"orchestrator-subagents",domainId:"agentic-architecture",title:"Orchestrator & Subagents",summary:"Decompose oversized agents into a coordinating orchestrator plus scoped subagents with explicit context contracts.",objectives:["Recognize when a single agent has outgrown its tool surface and context","Design orchestrator/subagent boundaries around capabilities and risk","Pass context between agents with structured summaries instead of raw transcripts","Explain the cost and latency consequences of adding orchestration layers"],explanation:{heading:"Concept",body:["An orchestrator is an agent whose job is planning and routing rather than doing. It decomposes a goal, dispatches subtasks to subagents that each own a narrow tool set and system prompt, then integrates their structured results. Each subagent runs its own loop with its own budget.","The boundary rule: one capability area per subagent, and no subagent receives more context than it needs to act. Findings travel upward as structured summaries — key facts, citations, confidence — never as full conversation transcripts."]},whyItMatters:["Task Statement 1.3 of the blueprint covers subagent invocation, context passing, and spawning directly.","Orchestration is the standard fix for tool-selection confusion and unbounded prompt growth in production incidents.","Every layer adds latency and cost; knowing when NOT to orchestrate is equally testable."],diagram:"workflow-patterns",simpleExample:{title:"Research-and-write pipeline",body:"An orchestrator splits 'write a briefing on topic X' into research and drafting subagents. The researcher returns sources with relevance scores; the writer receives only those summaries.",code:{label:"orchestrator.ts",language:"typescript",code:`const plan = await orchestrator("Brief me on MCP adoption");

for (const task of plan.subtasks) {
  const subagent = task.kind === "research" ? researcher : writer;
  const result = await subagent.run({
    instruction: task.instruction,
    context: task.requiredContext,
  });
  orchestrator.observe(task.id, result.summary);
}

return orchestrator.finalize();`}},productionExample:{title:"Security review service",body:"A platform team replaced one 20-tool review agent with an orchestrator and three subagents: repo scanner (read-only git tools), dependency auditor (SBOM tools), and report generator (no tools, template-bound output). Orchestrator-to-subagent payloads are typed JSON with file lists and finding IDs, capped at size limits. P95 latency rose 15% from the extra hops while false-positive rates fell by half because each scanner sees only relevant tools."},antiPattern:{name:"Transcript forwarding",wrong:"Pasting a subagent's entire conversation history into the next agent's prompt 'so nothing is lost'.",consequence:"Context bloat, attention dilution, duplicated reasoning, and cost growth linear in team size instead of task size.",fix:"Require every subagent to return a structured summary object; forward only fields downstream agents actually consume."},tradeOffs:[{choice:"Adding an orchestration layer",gain:"Focused contexts, scoped permissions, parallelizable subtasks",cost:"Extra latency, serialization design work, harder end-to-end debugging"},{choice:"Parallel subagent dispatch",gain:"Wall-clock time drops for independent subtasks",cost:"Result merging complexity and higher concurrent API spend"},{choice:"Typed context contracts",gain:"Predictable handoffs, testable boundaries, easier regression hunts",cost:"Upfront schema design; brittle if task shapes churn frequently"}],handsOn:{title:"Split a monolithic agent",steps:["Take any agent with more than eight tools and list its distinct responsibilities.","Draw the orchestrator/subagent split on paper with one tool set per box.","Implement the smallest version: two subagents, JSON summaries, shared turn budget.","Measure cost and latency before vs after; record both numbers."]},examQuestionId:"q-subagent-context-passing",takeaway:"Orchestrate along capability boundaries, pass structured summaries, and let data prove the added hop is worth it.",tags:["orchestration","subagents","context passing"]},{id:"human-in-the-loop-gates",domainId:"agentic-architecture",title:"Human-in-the-Loop Gates",summary:"Insert programmatic approval boundaries where actions become irreversible, regulated, or high-blast-radius.",objectives:["Classify agent actions by reversibility and blast radius","Implement approval gates at the tool boundary rather than in prompts","Queue approvals so humans review asynchronously without blocking reads","Explain why self-reported confidence is a poor gate signal"],explanation:{heading:"Concept",body:["Not all agent actions deserve equal scrutiny. Reading data is reversible; writing records, spending money, or sending email is not. A human-in-the-loop gate intercepts specific tool calls at execution time and converts them into proposals that queue for human approval.","The critical design choice is enforcement point. A system-prompt instruction like 'always ask before deleting' is a suggestion the model can forget under pressure. A permission layer that physically cannot execute the write until a human signs off is architecture."]},whyItMatters:["Blueprint scenarios repeatedly pair CRM/production access with mandatory human approval.","The distinction between programmatic enforcement and prompt-based rules is explicitly tested.","Approval queues resolve the tension between oversight and the support-team shift model."],simpleExample:{title:"Gated write tool",body:"The write path never mutates. It validates input, then returns a proposal payload tagged for the approval queue.",code:{label:"gate.ts",language:"typescript",code:`async function updateCustomerTier(input: TierChange) {
  validate(input);

  return {
    isError: true,
    content: [text(JSON.stringify({
      errorCategory: "permission",
      message: "Requires human approval",
      proposal: { ...input, status: "pending_approval" },
    }))],
  };
}`}},productionExample:{title:"Refund desk with dual thresholds",body:"A payments agent executes refunds below $50 automatically against a limited-balance credential. Refunds from $50 to $200 generate proposals reviewed within one business day. Anything above $200 pages an on-call approver. The gate lives in the tool executor, keyed by action class, not in any prompt. Audit logs tie every executed refund to its approving human and original conversation ID."},antiPattern:{name:"Confidence-score autopilot",wrong:"Letting the agent proceed autonomously whenever it self-reports high confidence before acting.",consequence:"Models are poorly calibrated about their own correctness; confident failures execute irreversible writes exactly when they should not.",fix:"Gate on action class and business thresholds enforced in code; route review attention using calibrated confidence trained on labeled outcomes, never free-text self-assessment."},tradeOffs:[{choice:"Gating every write",gain:"Maximum oversight and auditability",cost:"Approval queues become bottlenecks; automation value shrinks toward zero"},{choice:"Threshold-based gates",gain:"Low-risk volume stays fast; scrutiny scales with stakes",cost:"Threshold tuning requires incident history and periodic review"},{choice:"Async approval queues",gain:"Humans review on shift schedules without blocking the agent",cost:"Proposals can go stale; expiry and re-validation policies are required"}],handsOn:{title:"Add a gate to your MCP server",steps:["List every tool you have built and mark each read-only or mutating.","Convert one mutating tool into a proposal-returning gated tool.","Add a mock approval endpoint that flips proposals to executed.","Verify the agent communicates pending status honestly to users."],linkedLabId:"multi-agent-research"},examQuestionId:"q-confidence-gate-vs-threshold",takeaway:"Enforce oversight where actions execute, not where the model talks. Irreversibility defines the gate line.",tags:["human-in-the-loop","permissions","approval gates"]},{id:"state-management-sessions",domainId:"agentic-architecture",title:"State Management & Session Isolation",summary:"Distinguish ephemeral conversation state from durable application state and isolate each agent's context to prevent cross-contamination.",objectives:["Separate conversation history (ephemeral) from durable state (database, Redis, filesystem)","Enforce session isolation so subagents never share raw transcripts","Choose structured payloads over conversation replay when passing state between agents","Design cross-session memory using summaries and persistent stores instead of full history replay","Implement state checkpointing for crash recovery and human review of intermediate results"],explanation:{heading:"Concept",body:["Every agent session has two kinds of state: ephemeral conversation history that lives in the context window and durable application state that lives outside it. Conversation history grows with every turn and is discarded when the session ends. Durable state — database records, Redis keys, file contents — persists across sessions and must be explicitly managed.","Session isolation means each agent or subagent maintains its own conversation transcript. Sharing raw transcripts between agents pollutes context with irrelevant reasoning chains, tool calls, and false starts. Instead, pass structured results: typed objects containing only the findings, citations, and confidence scores the receiving agent needs.","Cross-session memory avoids replaying full histories by summarizing key facts and storing them in external systems. CLAUDE.md captures project-level knowledge that persists across all sessions. Session-specific facts go to databases or files with explicit schemas. Checkpointing intermediate state before risky tool calls enables crash recovery and offline human review without re-running the entire agent loop."]},whyItMatters:["Task Statement 1.1 covers context-window management — understanding what stays in versus outside context is directly tested.","Every extra token of forwarded transcript costs money and dilutes attention; session isolation is the primary cost-control mechanism.","Crash recovery and auditability require persisted intermediate state; without checkpoints, failures mean full replays."],diagram:"workflow-patterns",simpleExample:{title:"Separating context from durable state",body:"The agent keeps only active task context in the conversation window while persisting durable facts to an external store. On session restart, it loads facts back instead of replaying history.",code:{label:"state-separation.ts",language:"typescript",code:`interface SessionState {
  conversationHistory: Message[];   // ephemeral — lives in context
  facts: Record<string, unknown>;   // durable — lives in Redis
  checkpoints: Checkpoint[];        // durable — lives in database
}

// Before risky tool call, checkpoint current state
async function checkpoint(state: SessionState) {
  await db.save({
    sessionId: state.conversationHistory[0].sessionId,
    facts: state.facts,
    lastTurn: state.conversationHistory.length,
    timestamp: Date.now(),
  });
}

// On session resume, load facts instead of replaying
async function resumeSession(sessionId: string): Promise<SessionState> {
  const saved = await db.load(sessionId);
  return {
    conversationHistory: [], // start fresh
    facts: saved.facts,      // restore durable state
    checkpoints: saved.checkpoints,
  };
}`}},productionExample:{title:"Multi-agent research pipeline with isolated sessions",body:"A research platform spawns three agents — a planner, a crawler, and a summarizer — each with its own session. The planner persists its decomposition plan and progress to a database after each subtask completes. The crawler stores raw page content in object storage and returns only extracted facts as structured payloads. The summarizer receives a typed array of { source, excerpt, relevanceScore } objects and never sees either agent's conversation history. If the crawler crashes mid-run, the planner reads the last checkpoint, identifies which pages were already processed, and resumes without re-crawling. Total cost stays predictable because context window usage is bounded by the current subtask's payload, not the full pipeline history."},antiPattern:{name:"Transcript replay across sessions",wrong:"Storing the full conversation history and replaying it into the next agent's context window to maintain continuity.",consequence:"Context window fills with irrelevant tool calls and reasoning traces from prior agents, reducing available space for the current task and increasing cost per turn.",fix:"Persist only structured summaries and extracted facts to an external store. On session resume or cross-agent handoff, load the summary — never the raw transcript."},tradeOffs:[{choice:"Keeping state in context vs external store",gain:"In-context state requires no infrastructure and is immediately available to the model",cost:"Consumes limited context tokens; unbounded growth leads to truncation and lost information"},{choice:"Full transcript persistence vs summary snapshots",gain:"Full transcripts preserve every detail for debugging and audit",cost:"Storage and replay cost grow linearly; summaries are lossy but bounded"},{choice:"Eager checkpointing vs lazy checkpointing",gain:"Eager checkpoints before every tool call maximize crash recovery granularity",cost:"High write overhead; lazy checkpoints at subtask boundaries reduce I/O at the cost of coarser recovery"}],handsOn:{title:"Implement session isolation for a subagent pipeline",steps:["Define a typed summary interface for inter-agent payloads with fields for findings, sources, and confidence.","Add a checkpoint function that persists agent state to a file or database before each risky tool call.","Modify your orchestrator to pass only the summary object to the next agent, not the conversation history.","Simulate a crash mid-pipeline and verify the system resumes from the last checkpoint without replaying history."]},examQuestionId:"q-context-budget-math",takeaway:"Treat conversation history as ephemeral and bounded; persist durable facts externally; pass structured summaries between agents; and checkpoint before risky operations.",tags:["session isolation","state management","context boundaries","checkpointing"]},{id:"tool-design-contracts",domainId:"tool-design-mcp",title:"Tool Design Contracts",summary:"Treat every tool as a contract the model must be able to honor: explicit scope, documented formats, and machine-distinguishable outcomes.",objectives:["Write descriptions that state when to use a tool and when not to","Document parameters with units, formats, examples, and edge-case behavior","Choose granularity: consolidate chatty tools, split overloaded ones","Design outputs so distinct outcomes are structurally distinguishable"],explanation:{heading:"Concept",body:["Claude selects tools based on names, descriptions, and schemas alone. That makes the description a behavioral contract: it defines what the tool does, when it applies, what each parameter means, and what happens at the edges. Anything left implicit becomes a production bug discovered by the model on your users' behalf.","Granularity is the other half of the contract. Twenty overlapping tools confuse selection; one mega-tool that does five things produces malformed arguments. Aim for tools that map to single clear intentions."]},whyItMatters:["Domain 2 is 18% of the exam and tool design principles lead its task statements.","Most tool-use failures trace back to underspecified descriptions rather than model capability.","Structured, distinguishable outcomes are prerequisites for reliable agent branching."],simpleExample:{title:"Weak vs strong description",body:"Same tool, two contracts. The strong version states scope, format, empty-result behavior, and forbidden usage.",code:{label:"descriptions",language:"typescript",code:`weak: "Searches customers."

strong:
"Look up customers by name substring.
Returns array of {id, name, region, tier}.
IDs are 'cus_' prefixed strings — never invent them.
Returns an EMPTY list when nothing matches; that is a
normal result, not an error.
Do not use for order history — use get_orders instead.",
`}},productionExample:{title:"Tool audit at a fintech",body:"A team consolidated 23 CRM endpoints into 9 intention-named tools after logs showed 31% of calls failing schema validation. Every description gained parameter formats (dates as ISO-8601), explicit do-not-use guidance pointing at sibling tools, and documented empty-result semantics. Validation failures dropped below 3% within a week without any prompt changes — the contract was doing the work."},antiPattern:{name:"The do-everything endpoint",wrong:"Exposing one generic query tool whose behavior depends on undocumented flag combinations.",consequence:"The model guesses flag semantics, produces plausible-but-wrong queries, and cannot distinguish its mistake from a data absence.",fix:"Split by intention into separately named tools with their own schemas, or encode mutually exclusive modes as an enum parameter with documented cases."},tradeOffs:[{choice:"Verbose descriptions",gain:"Fewer misfires; correct selection in crowded tool sets",cost:"Token overhead on every request carrying the tool list"},{choice:"Fine-grained tools",gain:"Precise permissions per capability",cost:"Selection burden grows; sequences need more turns"},{choice:"Consolidated tools",gain:"Compact tool list; fewer round trips",cost:"Wider blast radius per call; harder permission scoping"}],handsOn:{title:"Contract checklist rewrite",steps:["Pick three tools you have built or use regularly.","Score each against: scope statement, parameter formats, edge cases, do-not-use, empty-result semantics.","Rewrite the weakest description and re-test selection accuracy with tricky phrasings.","Note which checklist item fixed the most failures."],linkedLabId:"mcp-server"},examQuestionId:"q-tool-granularity",takeaway:"A tool is a promise written for a non-human reader. If the contract has gaps, the model will find them in production.",tags:["tool design","schemas","descriptions"]},{id:"mcp-integration-architecture",domainId:"tool-design-mcp",title:"MCP Integration Architecture",summary:"Model Context Protocol standardizes how hosts reach external context: clients connect, servers expose tools, resources, and prompts over transports.",objectives:["Place responsibilities correctly across MCP hosts, clients, and servers","Choose between stdio and HTTP-based transports for local vs remote servers","Use resources for read-only context and tools for actions","Scope authentication and permissions at the server boundary"],explanation:{heading:"Concept",body:["An MCP host (Claude Desktop, Claude Code, your app) embeds an MCP client that maintains connections to MCP servers. Each server declares capabilities: tools (model-invoked actions), resources (application-driven read-only context), and prompts (reusable templates). Servers run out-of-process and communicate over transports — stdio for local child processes, Streamable HTTP for remote services.","Because servers are separate processes with their own credentials, they are natural permission boundaries. A server should hold exactly the upstream access its capability set requires — no shared god-credentials."]},whyItMatters:["MCP appears throughout Domain 2's task statements: clients, servers, resources, authentication, permissions.","Transport choice drives deployment shape: stdio means local install; HTTP enables centralized managed servers.","Resource-vs-tool classification questions are common because the distinction is architectural, not cosmetic."],diagram:"mcp-architecture",simpleExample:{title:"Capability map",body:"One server, correctly classified capabilities:",code:{label:"capabilities.ts",language:"typescript",code:`server.registerTool("create_ticket", {...});   // action -> tool
server.registerTool("search_tickets", {...});   // query   -> tool

server.registerResource(
  "team-rubric",                                // static docs
  "file://rubrics/support.md",
  async () => ({ contents: [{ uri, text }] })
);

server.registerResource(
  "ticket-timeline",                            // dynamic read-only
  "tickets://{id}/timeline",
  { template },
  async (uri, { id }) => ({ contents: [render(id)] })
);`}},productionExample:{title:"Fleet of scoped servers",body:"An enterprise runs three MCP servers behind one internal gateway: a GitHub server using a bot token limited to two repositories, a Data Warehouse server enforcing row-level security per user JWT, and an internal Wiki server with anonymous read. Each holds only its own credential; none can impersonate another. The gateway rate-limits per server, so a runaway loop in one integration cannot exhaust API budgets elsewhere."},antiPattern:{name:"God-token server",wrong:"One MCP server holding admin credentials across all systems because 'it is easier than scoping'.",consequence:"Any prompt injection or logic bug in any tool inherits admin reach across every connected system at once.",fix:"One credential scope per server, mapped to its declared capabilities. Prefer read-only service accounts; gate mutations behind approval workflows."},tradeOffs:[{choice:"stdio transport",gain:"Zero infrastructure; perfect for personal/local dev servers",cost:"Per-machine install; no central updates or observability"},{choice:"Streamable HTTP transport",gain:"Central hosting, auth, logging, versioned rollouts",cost:"Infrastructure, session management, network failure modes"},{choice:"Resources over re-fetching via tools",gain:"Applications control context injection; cheaper discovery",cost:"Model cannot self-serve dynamic lookups without a paired tool"}],handsOn:{title:"Extend the lab server",steps:["Add a static resource exposing your support rubric document.","Add a templated resource returning ticket timelines by ID.","Classify every existing capability as tool vs resource and justify each in one sentence.","Swap stdio for Streamable HTTP locally and note what breaks in your client config."],linkedLabId:"mcp-server"},examQuestionId:"q-mcp-resource-vs-tool",takeaway:"Clients connect, servers expose, transports carry. Scope every credential to the smallest set its capabilities require.",tags:["mcp","architecture","transports","auth"]},{id:"structured-errors-empty-results",domainId:"tool-design-mcp",title:"Structured Errors & Empty Results",summary:"Reliable agents need machine-distinguishable outcomes: empty results are data, transient failures deserve backoff, validation failures deserve correction, permission failures deserve escalation.",objectives:["Distinguish empty results from execution errors — and encode both distinctly","Classify every failure as transient, validation, or permission","Design error payloads with categories, messages safe for model consumption, and trace IDs","Match retry policy to failure class instead of retrying everything identically"],explanation:{heading:"Concept",body:["A tool call has four possible outcomes: success with data, success proving absence (empty result), failure that may succeed later (transient), and failure that cannot be fixed by repeating (validation or permission). Agents that cannot tell these apart either hallucinate around gaps or hammer failing endpoints.","The fix is a typed error envelope. Every non-success result carries an errorCategory, a human-readable message written for the model to act on ('amount_minor must be integer cents'), and a trace ID for observability. The agent loop branches on category: backoff-and-retry for transient, feed-back-to-model for validation, stop-and-escalate for permission.","Empty results sit outside the error axis entirely. 'No rows match' is a successful query whose answer is absence — returning an error for it triggers pointless retries and teaches the model to fear legitimate lookups."]},whyItMatters:["Error-handling task statements appear explicitly in Domain 2's exam blueprint.","During provider outages, category-blind retries amplify incidents instead of surviving them.","Compliance teams need audit trails that distinguish outages from misuse — stringly-typed errors make that impossible."],simpleExample:{title:"A typed error envelope",body:"One shape, three categories, branchable by code:",code:{label:"error-contract.ts",language:"typescript",code:`// Success with absence — NOT an error
{ ok: true, data: [] }

// Failure — always carries a category
{
  ok: false,
  errorCategory: "transient",   // | "validation" | "permission"
  message: "Upstream timeout after 3s; safe to retry",
  traceId: "req_7f3a",
}

// Loop policy
if (!res.ok) {
  if (res.errorCategory === "transient") await backoffAndRetry();
  else if (res.errorCategory === "validation") return resToModel(res);
  else escalateToHuman(res);
}`}},productionExample:{title:"Surviving a payment-provider outage",body:"A billing agent called a payment API that started returning 503s during a regional incident. Because every tool error carried errorCategory=transient plus jittered exponential backoff capped at five attempts, affected transactions queued and completed automatically when the provider recovered — no thundering herd, no duplicated charges (idempotency keys made retries safe). In the same quarter, validation-category errors cut silent data corruption to zero: malformed payloads went back to the model with the validator's exact complaint instead of retrying unchanged."},antiPattern:{name:"Retry everything, forever",wrong:"Wrapping every tool call in a generic retry-until-success loop because 'transient errors exist'.",consequence:"Invalid payloads retry hundreds of times unchanged, permission walls get hammered, outages receive amplified traffic, and logs fill with identical failures no auditor can classify.",fix:"Require categories on every error. Retry only transients — with caps and backoff. Return validations to the model with the specific complaint. Escalate permissions immediately."},tradeOffs:[{choice:"Rich typed error payloads",gain:"Deterministic branching, auditable incidents",cost:"More surface area to design and version"},{choice:"Empty-as-success convention",gain:"Model explores lookups confidently; no false alarms",cost:"Callers must check data.length rather than catch"},{choice:"Capped retries with idempotency keys",gain:"Safe automatic recovery from transient faults",cost:"Slightly slower worst case; key plumbing on mutations"}],handsOn:{title:"Add the error envelope to your lab server",steps:["Pick two tools in your MCP lab server and give every failure path the {ok, errorCategory, message, traceId} shape.","Make list-style tools return empty arrays instead of throwing when nothing matches.","Write the three-branch handler (backoff / model-feedback / escalate) around one tool and force each path artificially.","Log every error with its category and confirm you can query 'all permission failures this session' from logs alone."],linkedLabId:"mcp-server"},examQuestionId:"q-transient-vs-validation",takeaway:"Absence is data, transience deserves patience, mistakes deserve information, and boundaries deserve humans. Encode all four.",tags:["structured errors","retries","failure handling"]},{id:"mcp-auth-permissions",domainId:"tool-design-mcp",title:"MCP Auth & Permission Scoping",summary:"Credentials belong to infrastructure, scoped per user and capability, enforced at the server boundary — the model reasons about actions but never holds keys.",objectives:["Keep credentials out of model context entirely","Scope tokens per-user and per-capability using OAuth where users are involved","Enforce least privilege server-side so client claims cannot widen access","Gate irreversible mutations behind approval workflows even for authenticated callers"],explanation:{heading:"Concept",body:["An MCP server is a trust boundary: it holds upstream credentials and decides which capabilities callers may exercise. Authentication answers 'who is calling' (per-user OAuth identity, or a service account for machine callers); authorization answers 'may this identity invoke this capability' (scope checks mapped to declared tools).","The cardinal rule is that secrets never travel through model context. Tokens passed inside prompts leak into transcripts, traces, and occasionally completions. Instead, the host authenticates the user, the MCP client attaches credentials at the transport layer, and the server validates them before any tool executes.","Least privilege completes the design: a calendar server needs calendar.read and calendar.write scopes — not full mailbox admin 'for future features'. And because authentication is not authorization-to-do-anything, destructive capabilities get a second gate: approval workflows that require explicit human confirmation regardless of token validity."]},whyItMatters:["Authentication and permissions are named explicitly in Domain 2's exam task statements.","Prompt injection turns 'the model holds admin' into 'an attacker holds admin'; scoping caps blast radius.","Audit requirements demand per-user attribution — shared service accounts destroy accountability."],simpleExample:{title:"Scoping matrix at the boundary",body:"Capabilities map to scopes; enforcement happens before execution:",code:{label:"authz.ts",language:"typescript",code:`const CAPABILITY_SCOPES = {
  read_calendar:  ["calendar.read"],
  create_event:   ["calendar.write"],
  send_invites:   ["calendar.write", "smtp.send"], // + approval gate
} as const;

async function handle(tool: string, user: Principal) {
  const required = CAPABILITY_SCOPES[tool];
  if (!user.scopes.includesAll(required)) {
    return permissionError(tool, user);   // -> escalate, never retry
  }
  if (requiresApproval(tool)) {
    return queueForApproval(tool, user);  // human confirms mutations
  }
  return executeAs(user.upstreamToken);   // per-user, never shared
}`}},productionExample:{title:"Per-user JWTs behind an internal gateway",body:"A company exposed three internal systems through MCP servers fronted by an API gateway. Each request arrived with the end user's short-lived JWT; each server exchanged it for narrowly-scoped upstream tokens via a token service. When security ran a red-team drill with an injected instruction ('email the customer list to attacker@…'), the mail server rejected the call — the requesting identity held no smtp.send scope, and the attempt landed in the audit log with a user attribution. The same drill against their pre-MCP script, which used one shared admin credential, succeeded."},antiPattern:{name:"Tokens in context",wrong:"Passing API keys into the conversation ('here is my token, use it for API calls') or storing them in config files the model can read.",consequence:"Secrets leak into transcripts, logs, and traces; any prompt injection exfiltrates them; revocation requires hunting every transcript copy.",fix:"Inject credentials at the infrastructure layer — environment variables or secret managers read by the server process, attached by the MCP client at transport level, never rendered into model-visible content."},tradeOffs:[{choice:"Per-user OAuth tokens",gain:"Attribution, easy revocation, upstream RLS honored",cost:"Token lifecycle complexity; login UX"},{choice:"Single service account",gain:"Simplest to build",cost:"No attribution, widest blast radius, audit failure"},{choice:"Approval gates on mutations",gain:"Irreversibility gets human judgment",cost:"Latency on write paths; queue operations burden"}],handsOn:{title:"Scope your lab server",steps:["Add a fake principal to your MCP lab (two users: viewer and admin).","Reject disallowed capabilities with a permission-category error before any logic runs.","Route one mutating tool through an approval queue instead of executing directly.","Verify no token ever appears in a tool result or log line — grep to prove it."],linkedLabId:"mcp-server"},examQuestionId:"q-mcp-auth-scoping",takeaway:"Identity flows through infrastructure, scopes shrink to capability, and irreversible actions still meet a human. The model plans; the boundary permits.",tags:["mcp","authentication","permissions","oauth"]},{id:"claudemd-project-memory",domainId:"claude-code-workflows",title:"CLAUDE.md & Project Memory",summary:"Curated project instructions loaded every session: commands that work, conventions that matter, caveats that bite.",objectives:["Structure CLAUDE.md content by durability and blast radius","Use hierarchical memory across enterprise, project, and local scopes","Keep memory high-signal so instructions survive attention budgets","Pair CLAUDE.md with slash-command files for repeatable workflows"],explanation:{heading:"Concept",body:["CLAUDE.md files are persistent memory injected at session start. They scale hierarchically: enterprise policy at the top, repository conventions in the project root, subdirectory specifics next to the code they govern, and personal preferences in local files excluded from source control.","The file earns its place with signal density. Every line should change Claude's behavior: build/test commands verified to work, non-obvious conventions ('we use barrel exports only in lib/'), and gotchas ('migration step required before integration tests'). Prose essays and copied handbooks dilute attention."]},whyItMatters:["CLAUDE.md is named explicitly in Domain 3's first task statements.","Monorepo scenarios test whether you scope conventions to the right level instead of one giant file.","The interview pattern — having Claude ask clarifying questions before big changes — pairs with well-seeded memory."],simpleExample:{title:"High-signal CLAUDE.md",body:"Short sections, imperative voice, no biography:",code:{label:"CLAUDE.md",language:"markdown",code:`# Orders service

## Commands
- pnpm test --filter orders   (unit)
- pnpm db:migrate && pnpm test:e2e   (integration needs DB up)

## Conventions
- Route handlers live in src/routes/<resource>/index.ts
- All money math uses minor units (integer cents) — never floats
- Zod schemas co-located with route, exported for client reuse

## Gotchas
- Run migrations BEFORE e2e; CI does this via pretest hook
- Do not edit generated/ — regenerate with pnpm codegen`}},productionExample:{title:"Monorepo with layered memory",body:"A 40-service monorepo keeps a thin root CLAUDE.md (org-wide commit format, security rules), per-package CLAUDE.md files (framework quirks, test commands), and developer-local files for personal aliases. When the team migrated from Jest to Vitest, updating the three relevant package-level memories changed Claude Code's behavior everywhere on the next session — no prompts re-typed, no rules forgotten mid-task."},antiPattern:{name:"The handbook dump",wrong:"Pasting the entire engineering wiki into CLAUDE.md 'so nothing is missing'.",consequence:"Attention spreads across thousands of low-relevance tokens; the five instructions that matter get lost, and stale guidance actively misleads.",fix:"Curate ruthlessly. If an instruction has not changed behavior in a month, delete it. Link out to documents instead of inlining them."},tradeOffs:[{choice:"Root-level only memory",gain:"One place to maintain",cost:"Package-specific nuance drowns or contradicts siblings"},{choice:"Hierarchical memory",gain:"Right context at right scope; easy team-wide updates",cost:"More files to keep truthful as architecture evolves"},{choice:"Local (uncommitted) overrides",gain:"Personal workflow freedom without team noise",cost:"'Works on my machine' divergence if overused"}],handsOn:{title:"Author real project memory",steps:["Write a root CLAUDE.md for any repo you maintain using the four-section template.","Ask Claude Code to run your documented test command before and after adding it; compare behavior.","Add one nested CLAUDE.md where a subdirectory genuinely differs.","Delete one line per week that earned its place least."],linkedLabId:"claude-code-workflow-lab"},examQuestionId:"q-claudemd-hierarchy",takeaway:"Memory is curation, not storage. Every line must earn its attention cost every single session.",tags:["claude code","claudemd","memory","conventions"]},{id:"permissions-plan-mode-hooks",domainId:"claude-code-workflows",title:"Permissions, Plan Mode & Hooks",summary:"Programmatic guardrails: permission rules that physically bound actions, plan mode for high-stakes changes, hooks that intercept lifecycle events.",objectives:["Configure allow/ask/deny permission rules instead of prompt-based requests","Choose plan mode vs direct execution based on blast radius and ambiguity","Attach PreToolUse and PostToolUse hooks to enforce and normalize","Explain why programmatic enforcement beats asking nicely in the prompt"],explanation:{heading:"Concept",body:["Claude Code's safety model is layered. Permissions are declarative rules: always allow read-only git status, ask before any npm install, deny writes to infra/. Plan mode flips execution into explore-first: Claude surveys the codebase, proposes an approach, and waits for sign-off before touching files. Hooks are shell commands bound to lifecycle events — PreToolUse can veto or rewrite a call before execution; PostToolUse can validate or transform results after.","The unifying principle is programmatic enforcement. A rule in settings is deterministic; a sentence in CLAUDE.md is advisory. Use prose for judgment calls and machinery for boundaries."]},whyItMatters:["Hooks, permissions, and plan mode each have dedicated task statements in Domain 3.","PostToolUse normalization patterns appear verbatim in blueprint examples.","Plan-mode-vs-direct-execution choice questions mirror real code-review judgment calls."],simpleExample:{title:"Three layers in concert",body:"Permissions bound what is possible, hooks clean what passes, plan mode governs how much changes at once.",code:{label:".claude/settings.json + hook",language:"json",code:`{
  "permissions": {
    "allow": ["Bash(git diff:*)", "Read(*)"],
    "ask": ["Bash(npm install:*)"],
    "deny": ["Read(.env*)", "Edit(src/generated/**)"]
  }
}

// PostToolUse hook: normalize timestamps from any tool output
// claude hook runs scripts/normalize-dates.js with tool JSON
// on stdin; its stdout replaces the result the model sees.`}},productionExample:{title:"Compliance-bound monorepo",body:"A fintech denies all writes under `ledger/` except through reviewed PRs, requires plan mode whenever a task touches more than five files (enforced by a PreToolUse hook counting Edit attempts), and normalizes every Bash tool result through PostToolUse to strip secrets from stack traces before the model sees them. Auditors receive the settings files themselves as evidence of enforcement."},antiPattern:{name:"Prompt-based policing",wrong:"'Never touch the ledger directory' written in CLAUDE.md with no permission rule backing it.",consequence:"Under long sessions or aggressive refactors the instruction gets outweighed by task pressure, and the forbidden write happens anyway.",fix:"Mirror every hard boundary in permissions/hooks so violation is impossible, and let CLAUDE.md explain WHY the boundary exists."},tradeOffs:[{choice:"Strict deny-by-default",gain:"Predictable blast radius; audit-friendly",cost:"Constant approval interruptions slow trusted flows"},{choice:"Plan mode for everything",gain:"Human sign-off on all strategies",cost:"Trivial edits drown in ceremony"},{choice:"Heavy PostToolUse transformation",gain:"Model always sees normalized data",cost:"Hidden mutation layer complicates debugging when outputs surprise you"}],handsOn:{title:"Harden a workspace",steps:["Write permission rules: two allows, two asks, two denies matching your real fears.","Install a PostToolUse hook that uppercases any returned JSON 'status' field; verify the model sees the change.","Run one small bugfix in direct mode and one multi-file refactor in plan mode; compare review experience.","Attempt a denied action and confirm the block is structural, not behavioral."],linkedLabId:"claude-code-workflow-lab"},examQuestionId:"q-hook-posttooluse",takeaway:"Boundaries belong in configuration, not conversation. Reserve prompts for judgment; give machinery the rules.",tags:["permissions","plan mode","hooks","claude code"]},{id:"skills-commands-automation",domainId:"claude-code-workflows",title:"Skills, Custom Commands & Workflow Automation",summary:"Reusable skill files and slash commands encode repeatable workflows so Claude Code applies your team's patterns consistently without re-explaining.",objectives:["Create skill files that encapsulate multi-step workflows","Design custom slash commands with parameterized inputs","Chain skills with other tools and hooks for end-to-end automation","Version and share skills across a team via source control"],explanation:{heading:"Concept",body:["Skills are structured instruction files that teach Claude Code a specific workflow: how to scaffold a new API route, how to run a security audit, how to prepare a release. Unlike CLAUDE.md's global rules, skills are invoked on demand via slash commands and carry their own step-by-step procedure, expected inputs, and output format.","Custom commands extend the slash-command namespace. A `/deploy-check` command might run linting, type-checking, integration tests, and a diff summary in sequence. Skills compose: one command can invoke another, and hooks can gate or augment the chain. The result is a library of battle-tested workflows that new team members can run immediately."]},whyItMatters:["Skills and custom commands appear in Domain 3's task statements on workflow automation.","Reusable workflows reduce prompt engineering per task — encode once, invoke many times.","Team-shared skills are a force multiplier: senior patterns become executable without mentoring overhead."],simpleExample:{title:"A new-feature skill",body:"Skill file that guides Claude through adding a new API endpoint:",code:{label:".claude/skills/new-api-endpoint.md",language:"markdown",code:`# Skill: New API Endpoint

## Steps
1. Ask for resource name and HTTP method
2. Create route file at src/routes/<resource>/index.ts
3. Add Zod schema co-located with route
4. Write unit tests covering happy path + 1 error case
5. Update OpenAPI spec if one exists
6. Run \`pnpm test --filter <resource>\` to verify

## Output
Report: file created, tests passing, any warnings.`}},productionExample:{title:"Onboarding automation at a startup",body:"A 15-person team shipped 12 skill files covering their most common tasks: new endpoint, new migration, new React component, security audit, dependency update, and release prep. New engineers run `/skill new-endpoint` on day one and get the team's exact conventions — barrel exports, error shapes, test patterns — without reading wiki pages. After three months, 78% of routine tasks started via a skill command rather than ad-hoc prompting."},antiPattern:{name:"One mega-skill for everything",wrong:"A single 200-line skill file covering all possible workflows with branching logic.",consequence:"Claude gets confused by irrelevant steps, the skill breaks when any step changes, and nobody dares edit it.",fix:"One skill per clear intention. Keep each under 50 lines. Compose via slash-command chaining instead of conditional branching."},tradeOffs:[{choice:"Many small focused skills",gain:"Easy to maintain, test, and share; clear entry points",cost:"Team must know which skill to invoke; discovery overhead"},{choice:"Parameterized slash commands",gain:"Flexible inputs; one command handles variants",cost:"More complex validation; error messages must guide usage"},{choice:"Skills in source control",gain:"Version history, code review, team-wide availability",cost:"Requires discipline to keep skills truthful as codebase evolves"}],handsOn:{title:"Build a skill library",steps:["Write a skill for the task you repeat most often (new component, new route, etc.).","Test it by running the skill on a fresh branch — does Claude follow every step?","Create a slash command that chains two skills together.","Add a PreToolUse hook that validates the skill's output format."],linkedLabId:"claude-code-workflow-lab"},examQuestionId:"q-skill-design",takeaway:"Skills turn tribal knowledge into executable contracts. If you explain it twice, write it as a skill.",tags:["skills","commands","automation","claude code"]},{id:"ci-cd-integration",domainId:"claude-code-workflows",title:"CI/CD Integration & Automated Testing",summary:"Run Claude Code in pipelines for automated code review, test generation, and deployment validation — with the same permission and safety model as interactive use.",objectives:["Configure Claude Code for non-interactive CI environments","Use Claude for automated code review in pull request workflows","Generate and maintain test suites with CI-driven Claude invocations","Apply permission rules and hooks in pipeline contexts"],explanation:{heading:"Concept",body:["Claude Code runs in CI the same way it runs locally: it reads CLAUDE.md, respects permission rules, and executes hooks. The difference is non-interactive mode — no human in the loop for permission prompts, so deny-by-default and pre-approved allow-lists become critical.","Common CI patterns include: automated code review on pull requests (Claude reads the diff, flags issues, posts a summary), test generation (Claude writes tests for uncovered code), and deployment validation (Claude runs a smoke-test skill and reports results). Each pattern uses the same underlying skill/hook/permission infrastructure."]},whyItMatters:["CI/CD automation is explicitly named in Domain 3's task statements.","Pipeline contexts require understanding permission rules without interactive prompts.","Code review automation is a high-impact, low-risk entry point for agentic workflows."],simpleExample:{title:"CI code review step",body:"GitHub Actions step that runs Claude Code for PR review:",code:{label:".github/workflows/review.yml",language:"yaml",code:`- name: Claude Code Review
  run: |
    claude --print --dangerously-skip-permissions \\
      "Review the diff in this PR. Focus on:
       1. Security issues (injection, auth bypass)
       2. Performance regressions
       3. Missing error handling
       Output a structured summary with file:line references."
  env:
    ANTHROPIC_API_KEY: \${{ secrets.ANTHROPIC_API_KEY }}`}},productionExample:{title:"Automated test generation pipeline",body:"A team added a CI job that runs after every merge to main. Claude reads the new diff, identifies untested code paths, generates test files, and opens a follow-up PR. The job uses a custom skill that enforces the team's test conventions (Arrange-Act-Assert, no snapshot tests, coverage thresholds). Over six months, test coverage rose from 62% to 89% with zero manual test-writing effort for routine cases."},antiPattern:{name:"Skipping permissions in CI",wrong:"Using --dangerously-skip-permissions on every CI step because 'CI is trusted'.",consequence:"A compromised dependency or malicious PR diff triggers unrestricted file writes, secret reads, or network calls in the pipeline.",fix:"Use minimal allow-lists per CI job. Code review needs only Read + Bash(diff). Test generation needs Read + Write(test/**). Deny everything else."},tradeOffs:[{choice:"Claude code review in CI",gain:"Catches issues humans miss; consistent review quality",cost:"API costs per PR; false positives need tuning"},{choice:"Automated test generation",gain:"Coverage rises without manual effort",cost:"Generated tests need human review for correctness and intent"},{choice:"Non-interactive permissions",gain:"Pipelines run without human gates",cost:"Requires precise allow-lists; over-permissive rules create security gaps"}],handsOn:{title:"Add Claude to a CI pipeline",steps:["Create a GitHub Actions workflow that runs Claude Code on a PR diff.","Write a review skill with the team's specific focus areas.","Configure permission rules for the CI job: read-only where possible.","Run the workflow on a real PR and evaluate the review output quality."],linkedLabId:"claude-code-workflow-lab"},examQuestionId:"q-ci-permissions",takeaway:"CI is just another user of Claude Code — same rules, same skills, tighter permissions. Automate the repeatable, protect the dangerous.",tags:["ci/cd","automation","code review","testing","claude code"]},{id:"few-shot-structured-output",domainId:"prompt-engineering",title:"Few-Shot Prompting & Structured Output",summary:"Concrete input/output examples anchor format fidelity better than any prose, and JSON schemas make the contract enforceable.",objectives:["Select and order few-shot examples that cover the hard cases","Write system prompts with explicit instructions instead of vibes","Constrain outputs with JSON Schema and tool-based structured output","Separate content from metadata using tagged document sections"],explanation:{heading:"Concept",body:["Models imitate demonstrated behavior more reliably than described behavior. Two or three input/output pairs — including one deliberately messy edge case — anchor the target distribution far better than another paragraph of rules. Examples should be diverse where the task varies and identical where it must not.","Structured output closes the loop: define a JSON Schema for the response (via tool-use forced output or API structured-output features), so validation is mechanical. Inside long prompts, wrap each source document in tags with its metadata (source URL, title, date) so extracted claims can carry provenance."]},whyItMatters:["Few-shot examples are named as the most effective technique for consistently formatted output in blueprint study guidance.","Domain 4 weighs 20%; extraction pipelines are its signature scenario.","Provenance-aware prompting feeds directly into Domain 5's citation requirements."],simpleExample:{title:"Schema + examples",body:"The schema defines shape; the few-shot pairs demonstrate normalization of dirty input.",code:{label:"extract.ts",language:"typescript",code:`const invoiceSchema = {
  type: "object",
  properties: {
    vendor: { type: "string" },
    amount_minor: { type: "integer", description: "cents" },
    currency: { type: "string", enum: ["USD", "EUR", "GBP"] },
    due_date: { type: "string", description: "ISO-8601 or null" },
  },
  required: ["vendor", "amount_minor", "currency"],
};

// Example pair embedded before the real input:
// Input: "Acme GmbH — 1.240,50 EUR, payable 3/2026"
// Output: {"vendor":"Acme GmbH","amount_minor":124050,
//          "currency":"EUR","due_date":null}`}},productionExample:{title:"Insurance claim intake",body:"A carrier extracts claim fields from adjuster emails. The prompt carries three examples: clean email, multi-claim thread (must return array), and missing-date case (must return null, never guess). Output uses tool-forced JSON against the schema; a retry pass re-runs with the validator's error message appended when checks fail. Field-level accuracy rose from 91% to 98.6%, with every remaining miss caught by validation rather than reaching downstream systems."},antiPattern:{name:"Rule-of-the-week prompts",wrong:"Accumulating exception clauses ('if German number format then... if USD prefix...') until the prompt outgrows the task.",consequence:"Rules interact unpredictably, contradict older clauses, and still miss the next weird format — while token costs balloon.",fix:"Replace rule accretion with representative examples of each hard case plus a schema that makes ambiguity expressible (nulls, enums), letting the model generalize."},tradeOffs:[{choice:"More few-shot examples",gain:"Tighter format clustering on varied inputs",cost:"Latency and cost per call; stale examples mislead silently"},{choice:"Schema-enforced output",gain:"Mechanical validation; guaranteed parseable shape",cost:"Over-constrained schemas force fabrication when data is absent"},{choice:"Tagged document sections",gain:"Clean provenance; reduced cross-document confusion",cost:"Prompt assembly layer must handle escaping and nesting"}],handsOn:{title:"Beat the messy corpus",steps:["Collect five genuinely messy inputs from your own inbox/domain.","Write a zero-example prompt; record failure modes per field.","Add two examples targeting exactly those failures; add a third only if needed.","Enforce a schema allowing null for optional fields; measure again."],linkedLabId:"structured-api-app"},examQuestionId:"q-schema-fabrication",takeaway:"Show the format you want, schema what you will accept, and tag where everything came from.",tags:["few-shot","structured output","json schema","system prompts"]},{id:"validation-retries-evals",domainId:"prompt-engineering",title:"Validation, Retries & Evals",summary:"Close the quality loop: validate mechanically, retry with error context, and guard regressions with golden evaluation sets.",objectives:["Design retry loops that feed validator errors back as corrective context","Make schemas fabrication-proof with nullable fields and explicit absence semantics","Build golden eval sets that gate prompt and model changes","Apply multi-pass review with distinct rubrics instead of one overloaded pass"],explanation:{heading:"Concept",body:["A production prompt is a function under test. Wrap every call in validate → retry: run schema and business checks, and on failure re-invoke with the original input plus the specific errors ('amount_minor must be integer cents; you returned a float'). Two retries with escalating specificity catch most drift without masking systemic issues.","Evals are regression insurance. Freeze a golden set of inputs with expected outputs (or graded rubrics) covering each documented hard case; run it on every prompt change, model upgrade, or temperature tweak. A prompt that cannot be evaluated cannot be safely improved.","For review-shaped tasks, split passes by concern — factual accuracy pass, tone pass, policy pass — each with its own rubric, rather than asking one pass to optimize everything at once."]},whyItMatters:["Validation and retries are explicit Domain 4 topics; evaluation appears in both D4 and D5 task lists.","Multi-pass review patterns show up across blueprint scenarios for code review and document QA.","Regression protection is what makes iteration safe enough to do continuously."],simpleExample:{title:"Retry with error feedback",body:"The validator's message becomes the model's next instruction:",code:{label:"retry-loop.ts",language:"typescript",code:`let attempt = 0, output;
while (attempt < 3) {
  output = await generate(input, attempt > 0 ? errors : undefined);
  errors = validate(output, schema, businessRules);
  if (!errors.length) break;
  attempt++;
}
if (errors.length) throw new PipelineError(errors);

function validate(out, schema, rules) {
  const errs = ajv.validate(schema, out)
    ? [] : [ajv.errorsText()];
  if (Number.isInteger(out?.amount_minor) === false)
    errs.push("amount_minor must be integer cents");
  return [...errs, ...rules.map(checkBusiness)];
}`}},productionExample:{title:"Golden set gates a model migration",body:"A support-intent classifier team maintained 400 labeled tickets (30% adversarial edits like typos and injected instructions). When leadership pushed an early upgrade to the newest model, evals flagged a 7-point regression on refund-policy intents before rollout. The team shipped anyway only after adding three targeted few-shot examples that closed the gap — evidence over vibes, scheduled in CI nightly."},antiPattern:{name:"Infinite polite retries",wrong:"Re-sending identical requests on validation failure, hoping different output emerges.",consequence:"Tripled latency and cost with near-identical failures; systematic issues hide behind occasional lucky passes.",fix:"Every retry must add information: the precise validation errors, the offending output, and which rule failed. Cap attempts and escalate persistent failures to humans."},tradeOffs:[{choice:"Strict schema validation",gain:"Downstream systems trust every payload",cost:"Legitimately fuzzy cases bounce as errors unless schema allows nulls/enums"},{choice:"Error-informing retries",gain:"Self-correcting pipeline without human touch",cost:"Up to N× cost on pathological inputs; needs caps and alerting"},{choice:"Golden eval gating",gain:"Fearless iteration; objective model-comparison data",cost:"Set authorship effort; sets go stale as products evolve"}],handsOn:{title:"Ship a self-correcting extractor",steps:["Take your week-8 extraction prompt and add business-rule validators beyond schema.","Implement up-to-three retries appending formatted error messages.","Freeze ten golden inputs including two adversarial ones; script the eval.","Break your prompt on purpose; confirm evals catch it before you would have."],linkedLabId:"structured-api-app"},examQuestionId:"q-retry-error-context",takeaway:"Validate mechanically, retry informatively, evaluate continuously. Prompts are code; treat them like it.",tags:["validation","retries","evaluation","multi-pass review"]},{id:"system-prompt-architecture",domainId:"prompt-engineering",title:"System Prompt Architecture & Role Design",summary:"Structure system prompts as layered contracts: role definition, behavioral constraints, output format, and runtime context — each with clear boundaries.",objectives:["Design system prompts with distinct layers: role, rules, format, context","Use role definitions to anchor behavioral defaults without over-constraining","Separate immutable constraints from task-specific instructions","Manage prompt length to preserve attention for the most important directives"],explanation:{heading:"Concept",body:["A system prompt is a contract between your application and the model. Layer it deliberately: role definition sets the baseline persona and expertise; behavioral rules define hard constraints (never fabricate, always cite, refuse out-of-scope requests); output format specifies the response shape; and runtime context carries task-specific data injected per call.","The architecture matters because attention is finite. Directives at the top and bottom of a prompt receive more weight than those buried in the middle. Put your hardest constraints (safety, format) at the edges, and your softest guidelines (tone, style) where they can be outweighed by more important instructions if attention is tight."]},whyItMatters:["System prompt design is a core Domain 4 topic — the exam tests whether you can structure prompts for reliability.","Role definition quality directly impacts instruction-following consistency.","Prompt architecture determines how well instructions survive at scale across varied inputs."],simpleExample:{title:"Layered system prompt",body:"Four sections with clear responsibilities:",code:{label:"system-prompt.ts",language:"typescript",code:`const systemPrompt = \`
## Role
You are a financial data extraction assistant. You are precise, cautious, and never speculate.

## Rules (immutable)
- Return null for fields you cannot determine from the input
- Never invent numeric values or dates
- If the input is not financial data, return { error: "not_financial" }

## Output format
Respond with valid JSON matching this schema:
{ vendor: string, amount: number | null, currency: string, date: string | null }

## Context
Current task: extract invoice data from email text.
Today's date: \${new Date().toISOString().slice(0, 10)}
\`;`}},productionExample:{title:"Multi-tenant classification system",body:"A SaaS platform uses a base system prompt shared across tenants, with per-tenant context injected at runtime (industry-specific labels, compliance rules, output schemas). The base prompt defines the classifier role and universal constraints; tenant context adds domain-specific categories and examples. This separation means prompt improvements roll out to all tenants automatically while tenant-specific behavior stays configurable without prompt rewrites."},antiPattern:{name:"The wall-of-text prompt",wrong:"A single 3,000-token system prompt mixing role, rules, examples, context, and edge cases with no structure.",consequence:"Model attention scatters; critical safety rules buried at position 1,500 get overridden by later instructions; debugging which directive caused a behavior is impossible.",fix:"Layer and label each section. Put safety and format at top and bottom. Keep total length under 1,500 tokens for non-complex tasks. Link to external docs instead of inlining."},tradeOffs:[{choice:"Minimal role prompt",gain:"Maximum attention on task-specific instructions; fast inference",cost:"May under-specify behavior for edge cases"},{choice:"Comprehensive layered prompt",gain:"Consistent behavior across varied inputs; clear contracts",cost:"Token overhead; diminishing returns beyond ~1,500 tokens"},{choice:"Separate immutable vs. mutable sections",gain:"Safety rules survive prompt injection; clear audit trail",cost:"Prompt assembly layer adds complexity"}],handsOn:{title:"Architecture a production prompt",steps:["Take an existing prompt and separate it into four labeled layers.","Move safety-critical rules to the top and bottom of the prompt.","Measure token count — can you cut 20% without losing behavior?","Test with adversarial inputs: does the model respect constraints when the user tries to override them?"]},examQuestionId:"q-system-prompt-structure",takeaway:"Prompt architecture is information architecture. Layer by priority, separate by stability, and measure attention cost.",tags:["system prompts","role design","prompt architecture","instruction design"]},{id:"multi-pass-review",domainId:"prompt-engineering",title:"Multi-Pass Review & Chain-of-Thought Patterns",summary:"Split complex reasoning into distinct passes — each with its own rubric — so quality compounds instead of competing within a single generation.",objectives:["Design multi-pass pipelines where each pass has a single concern","Use chain-of-thought prompting to make reasoning traceable and debuggable","Apply self-critique patterns where the model evaluates its own output","Choose between single-pass and multi-pass based on task complexity"],explanation:{heading:"Concept",body:["Single-pass generation optimizes for one thing at a time. When a task requires multiple quality dimensions — factual accuracy, formatting, policy compliance, tone — asking the model to optimize all at once produces mediocre results across the board. Multi-pass review assigns each dimension its own pass with a specific rubric.","Chain-of-thought (CoT) makes the reasoning visible. Instead of asking for a final answer, prompt the model to show its work: 'First, identify the relevant facts. Then, evaluate each against the policy. Finally, render the decision.' CoT is especially powerful for audit-heavy domains where you need to verify the reasoning, not just the output."]},whyItMatters:["Multi-pass review patterns are explicit Domain 4 topics in the exam blueprint.","Code review and document QA scenarios test whether you can decompose evaluation into focused passes.","CoT is required for any task where reasoning traceability matters for compliance or debugging."],simpleExample:{title:"Two-pass document review",body:"Pass 1: factual accuracy. Pass 2: policy compliance. Each has a distinct rubric.",code:{label:"multi-pass.ts",language:"typescript",code:`// Pass 1: Accuracy
const accuracyResult = await generate({
  system: "Review the document for factual accuracy. For each claim, output: {claim, source?, status: 'verified'|'unverified'|'contradicted'}",
  input: document,
});

// Pass 2: Policy compliance (uses Pass 1 output)
const complianceResult = await generate({
  system: "Review this document for policy compliance. Flag: {section, rule, severity, suggestion}",
  input: { document, accuracyReport: accuracyResult },
});`}},productionExample:{title:"Medical claim adjudication pipeline",body:"An insurer runs a three-pass pipeline for claim review: Pass 1 extracts structured fields with confidence scores; Pass 2 validates against policy rules (coverage limits, pre-authorization requirements); Pass 3 generates the adjudication letter with reasoning. Each pass has its own eval set. The pipeline auto-approves 73% of claims with 99.7% accuracy; the remaining 27% go to human adjusters with the full reasoning trace attached."},antiPattern:{name:"Everything-in-one-pass",wrong:"Asking a single prompt to extract data, check compliance, and write a summary simultaneously.",consequence:"The model trades off between dimensions; extraction errors compound into wrong compliance checks; the summary inherits both failures.",fix:"Decompose into passes by concern. Each pass validates independently before feeding the next. Budget tokens per pass rather than trying to do everything in one generation."},tradeOffs:[{choice:"Multi-pass pipeline",gain:"Each dimension gets focused attention; easier to evaluate and debug",cost:"Higher latency and cost; inter-pass data must be structured"},{choice:"Chain-of-thought in single pass",gain:"Reasoning is visible without separate passes; moderate cost increase",cost:"Longer generations; model may rationalize errors in its reasoning"},{choice:"Self-critique pass",gain:"Catches own errors without external validation",cost:"Model may be over-confident in self-assessment; needs calibration"}],handsOn:{title:"Build a review pipeline",steps:["Take a task you currently do in one prompt and split it into 2-3 focused passes.","Define a rubric for each pass (3-5 criteria with pass/fail).","Measure quality improvement: does the multi-pass pipeline catch errors the single pass misses?","Add a self-critique step: ask the model to rate its own output against the rubric."]},examQuestionId:"q-multi-pass-review",takeaway:"One pass per concern, one rubric per pass. Quality compounds when dimensions don't compete.",tags:["multi-pass","chain-of-thought","review patterns","self-critique"]},{id:"context-degradation-summarization",domainId:"context-reliability",title:"Context Degradation & Summarization",summary:"Long sessions decay: attention dilutes, early details fade, cost compounds. Fight back with checkpoint summaries and compact resumes.",objectives:["Recognize degradation symptoms: contradictions, forgotten constraints, super-linear cost","Design checkpoint summarization that preserves durable state","Choose between session resumption and fresh start with carried state","Preserve provenance so compressed context stays verifiable"],explanation:{heading:"Concept",body:["Context windows are not free memory. As conversations grow, models weight recency heavily; instructions from turn 3 compete with 80 later turns for attention. Symptoms surface gradually: the agent re-asks answered questions, contradicts earlier commitments, or cites details that were never provided.","The countermeasure is active context management. At checkpoints — resolved threads, completed subtasks — compress history into structured state (open items, decisions, user preferences with source references). Resume from compact state plus recent turns instead of the full transcript. When prior context is mostly still valid, resume it and prune; when it is mostly stale or compromised, start fresh but carry forward the distilled state object."]},whyItMatters:["Context degradation, summarization, and session management headline Domain 5's task statements.","Blueprint scenarios test resumption-vs-restart judgment under realistic support-desk conditions.","Provenance requirements connect compression to auditability — you may not cite what you discarded without keeping its source."],simpleExample:{title:"Checkpoint compaction",body:"Every N turns, fold resolved threads into a state document and restart context from it:",code:{label:"compaction.ts",language:"typescript",code:`interface SessionState {
  openItems: { id: string; summary: string; owner: string }[];
  decisions: { decision: string; basis: string; source: string }[];
  userPrefs: { key: string; value: string; learnedAt: number }[];
}

async function checkpoint(history: Message[]): Promise<SessionState> {
  const { state } = await extract(JSON.stringify(history), stateSchema);
  return mergeWithPrior(priorState, state);
}

// New session seed = compact state + last K raw turns`}},productionExample:{title:"Six-hour support marathon",body:"A helpdesk agent checkpoints every ten exchanges: resolved tickets collapse into two-line entries with ticket IDs preserved as provenance anchors. Late in a six-hour session the agent still quotes the customer's original constraint verbatim — because the checkpoint stored the quote and its source turn, not a vague paraphrase. Token spend per exchange dropped 55% versus full-transcript operation while contradiction incidents went to zero over four weeks of shadow traffic."},antiPattern:{name:"Sentiment-triggered escalation",wrong:"Escalating to humans when the customer sounds angry, or trusting the agent's self-reported certainty.",consequence:"Angry-but-simple tickets waste human time while calmly-stated complex failures churn unsolved; self-assessment correlates weakly with actual error rates.",fix:"Escalate on structural signals: policy category, monetary thresholds, repeated failed tool calls, and confidence scores calibrated against labeled outcomes."},tradeOffs:[{choice:"Full-transcript fidelity",gain:"Nothing explicitly lost",cost:"Attention dilution and costs grow until quality collapses"},{choice:"Aggressive summarization",gain:"Stable performance across long sessions",cost:"Lossy by design; provenance discipline required to stay auditable"},{choice:"Fresh start with state carry-over",gain:"Clean attention; removes poisoned context after failures",cost:"Reseeding logic must capture everything users expect remembered"}],handsOn:{title:"Feel the decay",steps:["Hold a 40-turn conversation with any assistant; note facts from turn 3 and re-verify them at turn 35.","Add checkpointing to your multi-agent prototype at every fifth turn.","Measure token spend and answer accuracy before vs after on a scripted long task.","Write your merge policy: which state fields always survive compaction?"],linkedLabId:"enterprise-support-agent"},examQuestionId:"q-session-resume-vs-fresh",takeaway:"Treat context as a cache you actively manage: checkpoint, compress with provenance, and resume deliberately.",tags:["context degradation","summarization","session management"]},{id:"reliability-escalation-observability",domainId:"context-reliability",title:"Reliability, Escalation & Observability",summary:"Production agents need typed failure paths, calibrated human routing, and traces that make every iteration debuggable after the fact.",objectives:["Propagate errors with categories that drive deterministic next actions","Route human review using calibrated confidence from labeled validation sets","Instrument agents with per-iteration traces linking inputs, outputs, cost","Explain provenance chains from final answer back to source documents"],explanation:{heading:"Concept",body:["Reliability is designed at three layers. Failure typing: every tool result distinguishes transient errors (timeout, 503 — retry with backoff), validation errors (bad input — fix input, never retry blindly), and permission errors (escalate, do not retry). Review routing: field-level confidence scores calibrated on labeled sets direct borderline outputs to humans, with thresholds tuned to review capacity. Observability: each loop iteration logs inputs, outputs, latency, token spend, and trace IDs so any answer can be replayed.","Provenance stitches it together: every factual claim in an agent's output should resolve through citations or state records back to a source document or tool response. Without that chain, postmortems become guesswork and audits become impossible."]},whyItMatters:["Error propagation, human review, escalation, and observability are all named Domain 5 topics.","Blueprint guidance explicitly calls out calibrated field-level scores over sentiment proxies.","Crash recovery and structured state persistence appear in Domain 1/5 crossover scenarios."],simpleExample:{title:"Typed error handling + tracing",body:"Category determines destiny:",code:{label:"failure-taxonomy.ts",language:"typescript",code:`switch (result.errorCategory) {
  case "transient":
    await backoffRetry(result.traceId); break;
  case "validation":
    return correctInputAndContinue(result.details);
  case "permission":
    return queueForHuman({ reason: result, provenance });
  default:
    return failClosed(result.traceId);
}
trace.emit("agent.iteration", { spanId, inputHash,
  outputHash, tokens, latencyMs });`}},productionExample:{title:"Claims triage with calibrated routing",body:"An insurer's intake agent outputs per-field confidence for extracted claim data. Thresholds were set from a labeled validation set of 2,000 historical claims so that auto-approved fields run at 99.5% precision; anything below threshold flows to adjusters sorted by confidence ascending. Every extraction writes a trace linking email → extraction span → validator results → final JSON. When a bug surfaced in date parsing, engineers replayed affected traces in minutes and identified exactly which claims needed reprocessing — no log archaeology required."},antiPattern:{name:"Stringly-typed failures",wrong:"Returning 'Error: something went wrong' from every failure path and letting the model improvise next steps.",consequence:"Transient outages cause infinite blind retries; permission walls get hammered; nothing distinguishable reaches dashboards.",fix:"Adopt the taxonomy (transient / validation / permission / empty) in every tool contract, and branch on the category in code — not in prose."},tradeOffs:[{choice:"Auto-retry transient errors",gain:"Self-healing during blips",cost:"Amplifies load during real outages without caps and jittered backoff"},{choice:"Calibrated confidence routing",gain:"Human attention lands where error risk actually lives",cost:"Requires labeled data and periodic recalibration as distribution drifts"},{choice:"Per-iteration tracing",gain:"Replayable postmortems; precise cost attribution",cost:"Storage volume and potential PII exposure requiring redaction layers"}],handsOn:{title:"Make one agent auditable",steps:["Classify every error path in your MCP server with the four-category taxonomy.","Emit one structured trace line per loop iteration (input/output hashes, tokens, latency).","Fabricate a labeled mini-set (20 examples) and compute precision at two confidence thresholds.","Trace one final answer back to its sources; note where the chain breaks."],linkedLabId:"enterprise-support-agent"},examQuestionId:"q-error-taxonomy-routing",takeaway:"Type your failures, calibrate your routing, and trace every hop — reliability is what remains when you can replay any decision.",tags:["reliability","observability","escalation","provenance"]},{id:"context-window-strategies",domainId:"context-reliability",title:"Context Window Optimization Strategies",summary:"Maximize signal per token: hierarchical context loading, progressive disclosure, semantic search retrieval, and dynamic context assembly.",objectives:["Design hierarchical context loading: summary → detail on demand","Use retrieval-augmented generation to inject only relevant context","Apply progressive disclosure to keep early context lightweight","Balance context completeness against attention dilution"],explanation:{heading:"Concept",body:["Context windows are expensive real estate. Every token competes for attention, so the goal is maximizing information density: put the most relevant context first, defer details to on-demand retrieval, and never include context 'just in case.'","Three strategies compound: hierarchical loading starts with a compact summary and drills into detail only when the task requires it. Retrieval-augmented generation (RAG) fetches relevant documents by semantic similarity rather than dumping the entire corpus. Progressive disclosure feeds context in stages — system prompt for identity and rules, initial context for the task, then expanding context as the model requests or the workflow requires."]},whyItMatters:["Context management is Domain 5's core topic — the exam tests whether you can keep agents coherent at scale.","RAG integration patterns appear across multiple domain blueprints.","Cost optimization through context management is a real-world architectural concern."],diagram:"context-window",simpleExample:{title:"Hierarchical context loading",body:"Load summary first, expand on demand:",code:{label:"context-loader.ts",language:"typescript",code:`interface ContextLayer {
  summary: string;        // Always loaded (~200 tokens)
  details: string[];      // Loaded on task match (~500 tokens each)
  fullDoc: () => Promise<string>; // Loaded on demand
}

async function assembleContext(task: string, layers: ContextLayer[]) {
  const context = layers.map(l => l.summary).join("\\n");
  const relevant = layers.filter(l =>
    l.details.some(d => task.includes(keyword(d)))
  );
  return context + "\\n" + relevant.map(r => r.details.join("\\n")).join("\\n");
}`}},productionExample:{title:"Customer support agent with RAG",body:"A support agent loads three context layers: (1) a 200-token company policy summary always present, (2) product-specific FAQs matched by ticket topic via embedding search, and (3) the customer's recent interaction history (last 5 messages). Full policy documents are available via a 'read more' tool the model can invoke when FAQ entries are insufficient. Token usage dropped 62% compared to loading all policies upfront, while first-contact resolution rate improved because the model focused on relevant context instead of drowning in noise."},antiPattern:{name:"Load everything, hope attention handles it",wrong:"Dumping the entire knowledge base into context because 'the model can handle 200k tokens'.",consequence:"Key instructions diluted across thousands of tokens; model cites irrelevant documents; cost balloons with no quality improvement.",fix:"Implement retrieval. Start with keyword matching, graduate to semantic search. Always have a summary layer that fits in the system prompt."},tradeOffs:[{choice:"RAG-based retrieval",gain:"Relevant context only; scalable to large corpora",cost:"Retrieval quality determines everything; embedding infrastructure needed"},{choice:"Hierarchical loading",gain:"Progressive detail; predictable token budget",cost:"Summary quality is critical; poor summaries cause missed context"},{choice:"Full context upfront",gain:"Zero retrieval latency; simple architecture",cost:"Attention dilution; cost scales linearly with corpus size"}],handsOn:{title:"Optimize a context budget",steps:["Audit a production prompt: how many tokens are loaded? How many are used?","Implement a two-layer system: summary always + detail on match.","Measure token usage and task quality before vs after.","Add a tool that lets the model request specific documents on demand."]},examQuestionId:"q-context-optimization",takeaway:"Context is a cache you actively manage. Load the minimum, retrieve the relevant, and summarize the rest.",tags:["context windows","RAG","optimization","retrieval"]},{id:"monitoring-alerting",domainId:"context-reliability",title:"Production Monitoring & Alerting for Agents",summary:"Instrument agentic systems with metrics, traces, and alerts that catch degradation before users do — and make every failure root-causeable.",objectives:["Define key metrics: latency, token cost, success rate, escalation rate per domain","Implement structured tracing that links user request → agent iterations → tool calls → final output","Design alerting rules based on metric thresholds and anomaly detection","Build dashboards that surface agent health at a glance"],explanation:{heading:"Concept",body:["Production agents need observability across four pillars: metrics (aggregate health signals), traces (individual request journeys), logs (debugging detail), and alerts (automated threshold violations). Without these, teams discover problems from user complaints rather than dashboards.","The most critical metrics for agentic systems are: p95 latency (how long users wait), token cost per request (budget compliance), success rate (task completion without escalation), and escalation rate (human intervention frequency). Each metric needs domain-level breakdowns so you can spot which domain is degrading."]},whyItMatters:["Observability is explicitly named in Domain 5's exam topics.","Production monitoring separates toy demos from deployable systems.","Alert design requires understanding both the metrics and the agent architecture to set meaningful thresholds."],simpleExample:{title:"Agent trace structure",body:"Every request produces a structured trace for debugging:",code:{label:"tracing.ts",language:"typescript",code:`interface AgentTrace {
  requestId: string;
  userId: string;
  domain: string;
  startTime: number;
  iterations: {
    step: number;
    toolCalls: { tool: string; latencyMs: number; ok: boolean }[];
    tokensUsed: number;
  }[];
  outcome: "completed" | "escalated" | "failed";
  totalLatencyMs: number;
  totalTokens: number;
}

function emitTrace(trace: AgentTrace) {
  metrics.increment("agent.request", { domain: trace.domain, outcome: trace.outcome });
  metrics.histogram("agent.latency", trace.totalLatencyMs, { domain: trace.domain });
  metrics.histogram("agent.tokens", trace.totalTokens, { domain: trace.domain });
  traces.export(trace); // to OpenTelemetry, Datadog, etc.
}`}},productionExample:{title:"Alerting on agent degradation",body:"A team monitors their support agent with three alert tiers: Info (escalation rate exceeds 15% for 10 minutes — investigate domain-specific degradation), Warning (p95 latency exceeds 30 seconds for 5 minutes — possible upstream slowdown), Critical (success rate drops below 80% for 5 minutes — page on-call). Alerts are domain-scoped so the team knows whether it's a billing-agent problem or a general infrastructure issue. During a vector database outage, the RAG retrieval alert fired first, before user complaints arrived."},antiPattern:{name:"Alert on everything",wrong:"Setting alerts on every metric at low thresholds because 'coverage is safety'.",consequence:"Alert fatigue; real issues buried in noise; team stops responding to pages.",fix:"Three tiers (info/warning/critical) with domain-scoped thresholds tuned to actual baseline metrics. Start wide, narrow after two weeks of data."},tradeOffs:[{choice:"Per-domain metric breakdowns",gain:"Precise diagnosis; domain-specific SLAs",cost:"More metrics to manage; higher storage costs"},{choice:"Structured tracing on every request",gain:"Full replayability; root-cause analysis in minutes",cost:"Storage volume; PII redaction required"},{choice:"Anomaly-based alerting",gain:"Catches novel failure modes without manual threshold tuning",cost:"Requires baseline data; can produce false positives during traffic spikes"}],handsOn:{title:"Instrument an agent",steps:["Add structured tracing to one agent loop (request → iterations → outcome).","Define three metrics: latency, token count, success rate — with domain labels.","Set up one alert at a realistic threshold based on observed baselines.","Simulate a failure and verify the alert fires before you would have noticed manually."]},examQuestionId:"q-agent-monitoring",takeaway:"You cannot improve what you cannot measure. Instrument first, optimize second, alert on what matters.",tags:["monitoring","alerting","observability","tracing","metrics"]}],a=t.reduce((e,t)=>(e[t.domainId]=(e[t.domainId]??0)+1,e),{});e.s(["lessonCountByDomain",0,a,"lessons",0,t],40333)}]);